/** Zone d'une position de jeu (x, y entre 0 et 1, (0,0) = coin bas gauche) ; la case de chemin la plus proche si on tombe sur un mur. */
export function zoneAt(x: number, y: number): ZoneCode | null {
  const n = GRID.length;
  const cx = Math.min(n - 1, Math.max(0, Math.floor(x * n))), cy = Math.min(n - 1, Math.max(0, Math.floor((1 - y) * n)));
  for (let r = 0; r <= 3; r++) {
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
      const c = GRID[cy + dy]?.[cx + dx];
      if (c && c !== ".") return c as ZoneCode;
    }
  }
  return null;
}
